pub fn picture(png_base64: &str) -> Result<PlainBlock, Failure> {
    let source = ImageSource::inline(MediaType::Png, Base64Data::new(png_base64)?);
    Ok(PlainBlock::Image(ImageBlock::new(BlockId::mint(), source)))
}

pub fn words(text: &str) -> Vec<String> {
    text.split(|character: char| !character.is_alphabetic())
        .filter(|word| !word.is_empty())
        .map(str::to_lowercase)
        .collect()
}

pub fn numbers(text: &str) -> Vec<u64> {
    text.split(|character: char| !character.is_ascii_digit())
        .filter_map(|digits| digits.parse().ok())
        .collect()
}
